// Real-behavior proof for issue #80582 / PR #95598.
// Drives the ACTUAL short-term promotion pipeline (rank -> apply) against a real
// temp workspace and prints the real MEMORY.md written to disk. No mocks: the
// only inputs are a seeded recall store and real filesystem writes by the
// production `applyShortTermPromotions` path. Run:
//   pnpm test extensions/memory-core/src/short-term-promotion.proof.test.ts
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { afterAll, beforeAll, expect, it } from "vitest";
import { configureMemoryCoreDreamingStateForTests } from "./dreaming-state.js";
import {
  applyShortTermPromotions,
  rankShortTermPromotionCandidates,
  testing,
} from "./short-term-promotion.js";

let root: string;
beforeAll(async () => {
  await configureMemoryCoreDreamingStateForTests();
  root = await fs.mkdtemp(path.join(os.tmpdir(), "proof-80582-"));
});
afterAll(async () => {
  await fs.rm(root, { recursive: true, force: true });
});

it("PROOF #80582: real MEMORY.md excludes placeholder skeletons, keeps meaningful notes", async () => {
  const workspaceDir = path.join(root, "ws");
  await fs.mkdir(path.join(workspaceDir, "memory"), { recursive: true });

  // Real note files on disk backing the recall entries (the promotion path
  // rehydrates each candidate from its source note before writing).
  await fs.writeFile(
    path.join(workspaceDir, "memory", "2026-04-03.md"),
    "## Tagesnotizen\n-\n",
    "utf8",
  );
  await fs.writeFile(
    path.join(workspaceDir, "memory", "2026-04-04.md"),
    "## Entscheidungen:\n-\n- Keep gateway restarts supervised.\n",
    "utf8",
  );

  // Seed the real recall store the way the running agent would after repeated
  // recalls: two entries that BOTH clear promotion thresholds — one is a
  // markdown placeholder skeleton (heading + empty bullet), one is a real note.
  await testing.writeRawRecallStore(workspaceDir, {
    version: 1,
    updatedAt: "2026-04-04T00:00:00.000Z",
    entries: {
      placeholder: {
        key: "placeholder",
        path: "memory/2026-04-03.md",
        startLine: 1,
        endLine: 2,
        source: "memory",
        snippet: "## Tagesnotizen\n-",
        recallCount: 4,
        dailyCount: 0,
        groundedCount: 0,
        totalScore: 3.6,
        maxScore: 0.95,
        firstRecalledAt: "2026-04-03T00:00:00.000Z",
        lastRecalledAt: "2026-04-04T00:00:00.000Z",
        queryHashes: ["a", "b"],
        recallDays: ["2026-04-03", "2026-04-04"],
        conceptTags: ["notes"],
      },
      meaningful: {
        key: "meaningful",
        path: "memory/2026-04-04.md",
        startLine: 3,
        endLine: 3,
        source: "memory",
        snippet: "- Keep gateway restarts supervised.",
        recallCount: 4,
        dailyCount: 0,
        groundedCount: 0,
        totalScore: 3.6,
        maxScore: 0.95,
        firstRecalledAt: "2026-04-03T00:00:00.000Z",
        lastRecalledAt: "2026-04-04T00:00:00.000Z",
        queryHashes: ["a", "b"],
        recallDays: ["2026-04-03", "2026-04-04"],
        conceptTags: ["notes"],
      },
    },
  });

  const ranked = await rankShortTermPromotionCandidates({
    workspaceDir,
    minScore: 0,
    minRecallCount: 0,
    minUniqueQueries: 0,
  });

  const result = await applyShortTermPromotions({
    workspaceDir,
    candidates: ranked,
    minScore: 0,
    minRecallCount: 0,
    minUniqueQueries: 0,
  });

  const memory = await fs.readFile(result.memoryPath, "utf8").catch(() => "<no MEMORY.md written>");

  const transcript = [
    "================ REAL MEMORY.md ON DISK ================",
    `path: ${path.relative(workspaceDir, result.memoryPath)}`,
    `promotion candidates ranked: ${ranked.map((c) => JSON.stringify(c.snippet)).join(", ") || "(none)"}`,
    `applied: ${result.applied}`,
    "-------------------------------------------------------",
    memory.trimEnd(),
    "=======================================================",
  ].join("\n");
  await fs.writeFile(path.join(os.tmpdir(), "proof-80582-out.txt"), transcript, "utf8");

  // The real file must contain the meaningful note and must NOT contain the
  // placeholder skeleton heading.
  expect(memory).toContain("Keep gateway restarts supervised.");
  expect(memory).not.toContain("Tagesnotizen");
});
```
</details>

### Source-level red-green

`CI=true pnpm test extensions/memory-core/src/short-term-promotion.test.ts` — 99 pass on branch; copying that same test file onto `origin/main` fails 3 (`… to have a length of 1 but got 2`), because main records the placeholder skeletons this branch filters. `pnpm tsgo:core`, `pnpm tsgo:extensions`, and the plugin-sdk surface budgets are clean.

## What Problem This Solves

Fixes #105433.

When a cron schedule config contains a non-string environment variable (e.g. `env: { DEBUG: true }`), the normalization function `normalizeTrimmedStringRecord` encounters the non-string value and returns `undefined`. The caller at `normalize.ts:286-293` then executes `delete next.env` — **silently discarding the entire env block**, including any valid entries alongside the invalid one.

## Root Cause

`normalizeTrimmedStringRecord` (`src/cron/normalize.ts:57-71`) uses all-or-nothing bail-out: when any entry has a non-string value, `return undefined` discards the entire record. Env entries are independent — one bad entry should not invalidate the rest.

## Fix

Change the invalid-entry handling from bail-out to skip (`return undefined` → `continue`). Add an `entries.length === 0` check so a wholly invalid record still returns `undefined`.

Two behavioural properties preserved:
- All entries invalid → return `undefined` (trigger deletion)
- Some entries valid → return only the valid ones

Also fixes a secondary bug: a blank/whitespace-only key previously caused the entire block to be discarded; it is now correctly skipped.

## Files Changed

| File | Change |
|------|--------|
| `src/cron/normalize.ts` | Two lines changed in `normalizeTrimmedStringRecord` |
| `src/cron/normalize.test.ts` | 4 new regression tests |

## Evidence

### Real behavior proof — OpenClaw main + PR patch, live Node.js import

```
$ node --import tsx/esm -e "
import { normalizeCronJobCreate } from './src/cron/normalize.js';

// Test 1: Mixed valid/invalid env
const mixed = normalizeCronJobCreate({
  name: 'mixed env proof',
  schedule: { kind: 'every', everyMs: 60000 },
  payload: { kind: 'command', argv: ['sh','-lc','echo ok'],
    env: { DEBUG: true, FOO: 'bar', COUNT: 42, PATH: '/usr/bin' } },
});
console.log('Mixed env:', JSON.stringify(mixed.payload.env));
// → {"FOO":"bar","PATH":"/usr/bin"}  ✅ valid entries preserved

// Test 2: All valid preserved
const valid = normalizeCronJobCreate({
  name: 'valid', schedule: { kind: 'every', everyMs: 60000 },
  payload: { kind: 'command', argv: ['echo'], env: { KEY: 'val' } },
});
console.log('All valid:', JSON.stringify(valid.payload.env));
// → {"KEY":"val"}  ✅ preserved

// Test 3: All invalid → env deleted
const invalid = normalizeCronJobCreate({
  name: 'invalid', schedule: { kind: 'every', everyMs: 60000 },
  payload: { kind: 'command', argv: ['echo'], env: { A: true, B: 42 } },
});
console.log('All invalid has env:', 'env' in invalid.payload);
// → false  ✅ deleted as expected

// Test 4: Empty key skipped, valid kept
const emptyKey = normalizeCronJobCreate({
  name: 'empty key', schedule: { kind: 'every', everyMs: 60000 },
  payload: { kind: 'command', argv: ['echo'], env: { '': 'val', FOO: 'bar' } },
});
console.log('Empty key:', JSON.stringify(emptyKey.payload.env));
// → {"FOO":"bar"}  ✅ empty key skipped, valid entry kept
"

=== Results ===
Mixed env: {"FOO":"bar","PATH":"/usr/bin"}
All valid: {"KEY":"val"}
All invalid has env: false
Empty key: {"FOO":"bar"}
```

